def table(rows,widths,header=True):
    data=[[P(str(v),'HeadCell' if header and i==0 else ('CellBold' if j==0 else 'Cell')) for j,v in enumerate(row)] for i,row in enumerate(rows)]
    t=Table(data,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
    st=[('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,LINE),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]
    st += [('BACKGROUND',(0,0),(-1,0),NAVY),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,LIGHT])] if header else [('ROWBACKGROUNDS',(0,0),(-1,-1),[colors.white,LIGHT])]
    t.setStyle(TableStyle(st)); return t
